#![no_std]
//! Shared raw syscall ABI wrappers for x86_64, AArch64, and RISC-V 64.
//! Return values are raw kernel results; negative values represent -errno.
#[cfg(not(any(target_arch="x86_64",target_arch="aarch64",target_arch="riscv64")))]
compile_error!("raw-syscall supports x86_64, aarch64, and riscv64 only");
#[inline(always)] pub unsafe fn syscall0(n:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall1(n:usize,a:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall2(n:usize,a:usize,b:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,in("rsi") b,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,in("x1") b,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,in("a1") b,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall3(n:usize,a:usize,b:usize,c:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,in("rsi") b,in("rdx") c,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,in("x1") b,in("x2") c,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,in("a1") b,in("a2") c,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall4(n:usize,a:usize,b:usize,c:usize,d:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,in("rsi") b,in("rdx") c,in("r10") d,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,in("x1") b,in("x2") c,in("x3") d,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,in("a1") b,in("a2") c,in("a3") d,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall5(n:usize,a:usize,b:usize,c:usize,d:usize,e:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,in("rsi") b,in("rdx") c,in("r10") d,in("r8") e,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,in("x1") b,in("x2") c,in("x3") d,in("x4") e,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,in("a1") b,in("a2") c,in("a3") d,in("a4") e,lateout("a0") r,options(nostack));r} }
#[inline(always)] pub unsafe fn syscall6(n:usize,a:usize,b:usize,c:usize,d:usize,e:usize,f:usize)->isize { #[cfg(target_arch="x86_64")] {let r:isize;core::arch::asm!("syscall",in("rax") n,in("rdi") a,in("rsi") b,in("rdx") c,in("r10") d,in("r8") e,in("r9") f,lateout("rax") r,out("rcx") _,out("r11") _,options(nostack));r} #[cfg(target_arch="aarch64")] {let r:isize;core::arch::asm!("svc #0",in("x8") n,in("x0") a,in("x1") b,in("x2") c,in("x3") d,in("x4") e,in("x5") f,lateout("x0") r,options(nostack));r} #[cfg(target_arch="riscv64")] {let r:isize;core::arch::asm!("ecall",in("a7") n,in("a0") a,in("a1") b,in("a2") c,in("a3") d,in("a4") e,in("a5") f,lateout("a0") r,options(nostack));r} }
